function restoreCoArtifactsForStep(
  runDir: string,
  stepName: StepName,
  artifacts: ArtifactMap,
  log: Logger,
): void {
  for (const name of CO_ARTIFACTS_BY_STEP[stepName] ?? []) {
    const artifact = readPersistedStepArtifact(runDir, name, log);
    if (artifact === undefined) continue;
    artifacts[name] = artifact;
    log.info('checkpoint.co_artifact', `Restored ${name} co-artifact for checkpointed ${stepName}`);
  }
}

