/** Stand-in vendorq client used only when none is wired (eval harness / unit
 *  drivers). Every method throws a VendorqQueryError, so a vendor tool
 *  constructed without a real client still builds, and only fails — as a
 *  structured tool error via the tool's catch — if it is actually executed. A
 *  real pipeline run always wires `services.vendorClient`. */
const UNWIRED_VENDOR_CLIENT: VendorqClient = new Proxy({} as VendorqClient, {
  get() {
    return () => {
      throw new VendorqQueryError(
        'VENDOR_PROVIDER_UNAVAILABLE',
        'no vendorq client wired for this run; vendor reads are unavailable',
      );
    };
  },
});

/** Slice 2B ticket C3: same unwired-fallback shape as `UNWIRED_VENDOR_CLIENT`.
 *  `services.feedqPath` is set on every real run (`agents/pipeline/index.ts`);
 *  it is absent only in unit drivers / the eval harness that build a registry
 *  without going through the orchestrator. Building a step's feed tools never
 *  requires a wired path — the fail-closed boundary lands on the read, not on
 *  construction, exactly like the vendor client above. */
const UNWIRED_FEED_CLIENT: FeedqClient = new Proxy({} as FeedqClient, {
  get() {
    return () => {
      throw new FeedqQueryError('no feedq path wired for this run; feed reads are unavailable');
    };
  },
});

